static inline double MagickMax(const double x,const double y)
{
  if (x > y)
    return(x);
  return(y);
}

virtual void ComputeWithReservedSpace(OpKernelContext* context,
                                      bool use_reserved_space) {
  Tensor x = context->input(0);
  const Tensor& scale = context->input(1);
  const Tensor& offset = context->input(2);
  const Tensor& estimated_mean = context->input(3);
  const Tensor& estimated_variance = context->input(4);
  const Tensor* side_input = has_side_input_ ? &context->input(5) : nullptr;

  OP_REQUIRES(context, x.dims() == 4 || x.dims() == 5,
              errors::InvalidArgument("input must be 4 or 5-dimensional",
                                      x.shape().DebugString()));
  OP_REQUIRES(context, scale.dims() == 1,
              errors::InvalidArgument("scale must be 1-dimensional",
                                      scale.shape().DebugString()));
  OP_REQUIRES(context, offset.dims() == 1,
              errors::InvalidArgument("offset must be 1-dimensional",
                                      offset.shape().DebugString()));
  OP_REQUIRES(context, estimated_mean.dims() == 1,
              errors::InvalidArgument("estimated_mean must be 1-dimensional",
                                      estimated_mean.shape().DebugString()));
  OP_REQUIRES(
      context, estimated_variance.dims() == 1,
      errors::InvalidArgument("estimated_variance must be 1-dimensional",
                              estimated_variance.shape().DebugString()));
  bool use_reshape = (x.dims() == 5);
  auto x_shape = x.shape();
  TensorShape dest_shape;
  if (use_reshape) {
    const int64 in_batch = GetTensorDim(x, tensor_format_, 'N');
    int64 in_planes = GetTensorDim(x, tensor_format_, '0');
    int64 in_rows = GetTensorDim(x, tensor_format_, '1');
    int64 in_cols = GetTensorDim(x, tensor_format_, '2');
    const int64 in_depth = GetTensorDim(x, tensor_format_, 'C');
    dest_shape = ShapeFromFormat(tensor_format_, in_batch,
                                 {{in_planes, in_rows * in_cols}}, in_depth);
    OP_REQUIRES(context, x.CopyFrom(x, dest_shape),
                errors::InvalidArgument("Error during tensor copy."));
  }

  if (has_side_input_) {
    OP_REQUIRES(context, side_input->shape() == x.shape(),
                errors::InvalidArgument(
                    "side_input shape must be equal to input shape: ",
                    side_input->shape().DebugString(),
                    " != ", x.shape().DebugString()));
  }

  if (activation_mode_ != FbnActivationMode::kIdentity) {
    // NOTE(ezhulenev): This requirement is coming from implementation
    // details of cudnnBatchNormalizationForwardTrainingEx.
    OP_REQUIRES(
        context, !is_training_ || x.dim_size(3) % 4 == 0,
        errors::InvalidArgument("FusedBatchNorm with activation requires "
                                "channel dimension to be a multiple of 4."));
  }

  Tensor* y = nullptr;
  auto alloc_shape = use_reshape ? dest_shape : x_shape;
  OP_REQUIRES_OK(context, context->forward_input_or_allocate_output(
                              {0}, 0, alloc_shape, &y));

  Tensor* batch_mean = nullptr;
  OP_REQUIRES_OK(context, context->forward_input_or_allocate_output(
                              {3}, 1, scale.shape(), &batch_mean));
  Tensor* batch_var = nullptr;
  OP_REQUIRES_OK(context, context->forward_input_or_allocate_output(
                              {4}, 2, scale.shape(), &batch_var));
  Tensor* saved_mean = nullptr;
  OP_REQUIRES_OK(context,
                 context->allocate_output(3, scale.shape(), &saved_mean));
  Tensor* saved_maybe_inv_var = nullptr;
  OP_REQUIRES_OK(context, context->allocate_output(4, scale.shape(),
                                                   &saved_maybe_inv_var));

  if (is_training_) {
    functor::FusedBatchNorm<Device, T, U, true>()(
        context, x, scale, offset, estimated_mean, estimated_variance,
        side_input, epsilon_, exponential_avg_factor_, activation_mode_, y,
        batch_mean, batch_var, saved_mean, saved_maybe_inv_var,
        tensor_format_, use_reserved_space);
  } else {
    functor::FusedBatchNorm<Device, T, U, false>()(
        context, x, scale, offset, estimated_mean, estimated_variance,
        side_input, epsilon_, exponential_avg_factor_, activation_mode_, y,
        batch_mean, batch_var, saved_mean, saved_maybe_inv_var,
        tensor_format_, use_reserved_space);
  }
  if (use_reshape) {
    OP_REQUIRES(context, y->CopyFrom(*y, x_shape),
                errors::InvalidArgument("Error during tensor copy."));
  }
}

int ASN1_item_verify(const ASN1_ITEM *it, X509_ALGOR *a,
		ASN1_BIT_STRING *signature, void *asn, EVP_PKEY *pkey)
	{
	EVP_MD_CTX ctx;
	unsigned char *buf_in=NULL;
	int ret= -1,inl;

        int mdnid, pknid;

        EVP_MD_CTX_init(&ctx);

        /* Convert signature OID into digest and public key OIDs */
		{
		if (!pkey->ameth || !pkey->ameth->item_verify)
			{
			ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ASN1_R_UNKNOWN_SIGNATURE_ALGORITHM);
			goto err;
			}
		ret = pkey->ameth->item_verify(&ctx, it, asn, a,
							signature, pkey);
		/* Return value of 2 means carry on, anything else means we
		 * exit straight away: either a fatal error of the underlying
		 * verification routine handles all verification.
		 */
		if (ret != 2)
			goto err;
		ret = -1;
		}
	else
		{
		const EVP_MD *type;
		type=EVP_get_digestbynid(mdnid);
		if (type == NULL)
			{
			ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ASN1_R_UNKNOWN_MESSAGE_DIGEST_ALGORITHM);
			goto err;
			}

		/* Check public key OID matches public key type */
		if (EVP_PKEY_type(pknid) != pkey->ameth->pkey_id)
			{
			ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ASN1_R_WRONG_PUBLIC_KEY_TYPE);
			goto err;
			}

		if (!EVP_DigestVerifyInit(&ctx, NULL, type, NULL, pkey))
			{
			ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ERR_R_EVP_LIB);
			ret=0;
			goto err;
			}

		}

	inl = ASN1_item_i2d(asn, &buf_in, it);

	if (buf_in == NULL)
		{
		ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ERR_R_MALLOC_FAILURE);
		goto err;
		}

	if (!EVP_DigestVerifyUpdate(&ctx,buf_in,inl))
		{
		ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ERR_R_EVP_LIB);
		ret=0;
		goto err;
		}

	OPENSSL_cleanse(buf_in,(unsigned int)inl);
	OPENSSL_free(buf_in);

	if (EVP_DigestVerifyFinal(&ctx,signature->data,
			(size_t)signature->length) <= 0)
		{
		ASN1err(ASN1_F_ASN1_ITEM_VERIFY,ERR_R_EVP_LIB);
		ret=0;
		goto err;
		}
	/* we don't need to zero the 'ctx' because we just checked
	 * public information */
	/* memset(&ctx,0,sizeof(ctx)); */
	ret=1;
err:
	EVP_MD_CTX_cleanup(&ctx);
	return(ret);
	}

static bool list_intersect(struct ldb_context *ldb,
			   struct ldb_kv_private *ldb_kv,
			   struct dn_list *list,
			   const struct dn_list *list2)
{
	const struct dn_list *short_list, *long_list;
	struct dn_list *list3;
	unsigned int i;

	if (list->count == 0) {
		/* 0 & X == 0 */
		return true;
	}
	if (list2->count == 0) {
		/* X & 0 == 0 */
		list->count = 0;
		list->dn = NULL;
		return true;
	}

	/* the indexing code is allowed to return a longer list than
	   what really matches, as all results are filtered by the
	   full expression at the end - this shortcut avoids a lot of
	   work in some cases */
	if (list->count < 2 && list2->count > 10 && list2->strict == false) {
		return true;
	}
	if (list2->count < 2 && list->count > 10 && list->strict == false) {
		list->count = list2->count;
		list->dn = list2->dn;
		/* note that list2 may not be the parent of list2->dn,
		   as list2->dn may be owned by ltdb->idxptr. In that
		   case we expect this reparent call to fail, which is
		   OK */
		talloc_reparent(list2, list, list2->dn);
		return true;
	}

	if (list->count > list2->count) {
		short_list = list2;
		long_list = list;
	} else {
		short_list = list;
		long_list = list2;
	}

	list3 = talloc_zero(list, struct dn_list);
	if (list3 == NULL) {
		return false;
	}

	list3->dn = talloc_array(list3, struct ldb_val,
				 MIN(list->count, list2->count));
	if (!list3->dn) {
		talloc_free(list3);
		return false;
	}
	list3->count = 0;

	for (i=0;i<short_list->count;i++) {
		/* For the GUID index case, this is a binary search */
		if (ldb_kv_dn_list_find_val(
			ldb_kv, long_list, &short_list->dn[i]) != -1) {
			list3->dn[list3->count] = short_list->dn[i];
			list3->count++;
		}
	}

	list->strict |= list2->strict;
	list->dn = talloc_steal(list, list3->dn);
	list->count = list3->count;
	talloc_free(list3);

	return true;
}

connection_ap_rewrite_and_attach_if_allowed(entry_connection_t *conn,
                                            origin_circuit_t *circ,
                                            crypt_path_t *cpath)
{
  const or_options_t *options = get_options();

  if (options->LeaveStreamsUnattached) {
    CONNECTION_AP_EXPECT_NONPENDING(conn);
    ENTRY_TO_CONN(conn)->state = AP_CONN_STATE_CONTROLLER_WAIT;
    return 0;
  }
  return connection_ap_handshake_rewrite_and_attach(conn, circ, cpath);
}

static long madvise_remove(struct vm_area_struct *vma,
				struct vm_area_struct **prev,
				unsigned long start, unsigned long end)
 {
 	loff_t offset;
 	int error;

 	*prev = NULL;	/* tell sys_madvise we drop mmap_sem */

 	if (vma->vm_flags & (VM_LOCKED|VM_NONLINEAR|VM_HUGETLB))
 		return -EINVAL;

	if (!vma->vm_file || !vma->vm_file->f_mapping
		|| !vma->vm_file->f_mapping->host) {
 			return -EINVAL;
 	}

	if ((vma->vm_flags & (VM_SHARED|VM_WRITE)) != (VM_SHARED|VM_WRITE))
		return -EACCES;

 	offset = (loff_t)(start - vma->vm_start)
 			+ ((loff_t)vma->vm_pgoff << PAGE_SHIFT);

	/* filesystem's fallocate may need to take i_mutex */
 	up_read(&current->mm->mmap_sem);
	error = do_fallocate(vma->vm_file,
 				FALLOC_FL_PUNCH_HOLE | FALLOC_FL_KEEP_SIZE,
 				offset, end - start);
 	down_read(&current->mm->mmap_sem);
 	return error;
 }

static void coroutine_fn v9fs_xattrcreate(void *opaque)
{
    int flags;
    int32_t fid;
    int64_t size;
    ssize_t err = 0;
    V9fsString name;
    size_t offset = 7;
    V9fsFidState *file_fidp;
    V9fsFidState *xattr_fidp;
    V9fsPDU *pdu = opaque;

    v9fs_string_init(&name);
    err = pdu_unmarshal(pdu, offset, "dsqd", &fid, &name, &size, &flags);
    if (err < 0) {
        goto out_nofid;
    }
    trace_v9fs_xattrcreate(pdu->tag, pdu->id, fid, name.data, size, flags);

    file_fidp = get_fid(pdu, fid);
    if (file_fidp == NULL) {
        err = -EINVAL;
        goto out_nofid;
    }
    /* Make the file fid point to xattr */
    xattr_fidp = file_fidp;
    xattr_fidp->fid_type = P9_FID_XATTR;
    xattr_fidp->fs.xattr.copied_len = 0;
    xattr_fidp->fs.xattr.len = size;
     xattr_fidp->fs.xattr.flags = flags;
     v9fs_string_init(&xattr_fidp->fs.xattr.name);
     v9fs_string_copy(&xattr_fidp->fs.xattr.name, &name);
    xattr_fidp->fs.xattr.value = g_malloc(size);
     err = offset;
     put_fid(pdu, file_fidp);
 out_nofid:
    pdu_complete(pdu, err);
    v9fs_string_free(&name);
}

